@tool
extends Node

func run() -> Dictionary:
	var rep := {"deleted": [], "errors": []}
	var f := FileAccess.open("res://tools/gc_cleanup_ops.json", FileAccess.READ)
	var txt := f.get_as_text()
	f.close()
	var ops = JSON.parse_string(txt)
	var d := DirAccess.open("E:/")
	var PROJ := "ghost-company-main/"
	for src in ops.get("delete", []):
		var s := String(src)
		var from_rel := PROJ + s.substr(6)
		if d.dir_exists(from_rel):
			var okdel := d.remove_recursive(from_rel)
			if okdel == OK:
				rep["deleted"].append(s)
			else:
				rep["errors"].append({"op": "delete", "src": s, "error": str(okdel)})
		elif FileAccess.file_exists(s):
			d.remove(from_rel)
			if FileAccess.file_exists(s + ".import"):
				d.remove(from_rel + ".import")
			rep["deleted"].append(s)
		else:
			rep["errors"].append({"op": "delete", "src": s, "error": "missing"})
	return rep
